    0 // rotation
    0 //current sector the player is in
}

numSect 12 //total amount of sectors

sector
{ //0th sector, starting room
    -35 //floor
    10 //ceiling
    4 //amount of walls in the sector
    p //vertices
        -70 70 //must be done counterclockwise for normals to not be inverted
        -70 -70
        70 -70
        70 70
        -70 70
    p
    n //neighbors
        -1 //-1 is a normal wall
        -1
        -1
        1 //1 means this wall connects to that index of a sector
    n
}

